import type { Contact, Prisma } from "@prisma/client";
import { db } from "./db";

/**
 * Identity resolution. A contact can be addressed by any of:
 *   - externalId  — your system's user id (authoritative once known)
 *   - email
 *   - anonymousId — generated by the SDK on first launch, before sign-in
 *   - contactId   — Dispatch's own id
 *
 * When a device that was anonymous signs in (identify with both anonymousId
 * and externalId), its anonymous profile is either promoted (no known profile
 * yet) or merged into the existing known profile — devices, events, message
 * history and subscription state move over, so no engagement history is lost.
 */
export interface IdentityRef {
  contactId?: string | null;
  externalId?: string | null;
  email?: string | null;
  anonymousId?: string | null;
}

export function hasIdentity(ref: IdentityRef): boolean {
  return !!(ref.contactId || ref.externalId || ref.email || ref.anonymousId);
}

/** Look a contact up without creating or merging anything. */
export async function findContact(ref: IdentityRef): Promise<Contact | null> {
  if (ref.contactId) return db.contact.findUnique({ where: { id: ref.contactId } });
  if (ref.externalId) {
    const c = await db.contact.findUnique({ where: { externalId: ref.externalId } });
    if (c) return c;
  }
  if (ref.email) {
    const c = await db.contact.findUnique({ where: { email: ref.email.toLowerCase() } });
    if (c) return c;
  }
  if (ref.anonymousId) return db.contact.findUnique({ where: { anonymousId: ref.anonymousId } });
  return null;
}

/**
 * Find-or-create the contact for a reference, merging an anonymous profile
 * into the known one when both exist. `profile` fields are applied on the way.
 */
export async function resolveContact(
  ref: IdentityRef,
  profile: Omit<Prisma.ContactUpdateInput, "externalId" | "anonymousId"> = {}
): Promise<Contact | null> {
  if (ref.contactId) {
    const c = await db.contact.findUnique({ where: { id: ref.contactId } });
    return c && Object.keys(profile).length ? db.contact.update({ where: { id: c.id }, data: profile }) : c;
  }

  const email = ref.email?.toLowerCase() || null;
  const known = ref.externalId
    ? await db.contact.findUnique({ where: { externalId: ref.externalId } })
    : null;
  const byEmail = !known && email ? await db.contact.findUnique({ where: { email } }) : null;
  const anon = ref.anonymousId
    ? await db.contact.findUnique({ where: { anonymousId: ref.anonymousId } })
    : null;

  let target = known ?? byEmail;

  if (target && anon && anon.id !== target.id) {
    await mergeContacts(anon.id, target.id);
    target = await db.contact.findUnique({ where: { id: target.id } }); // pick up merged fields
  } else if (!target && anon) {
    target = anon; // promote the anonymous profile
  }

  const data: Prisma.ContactUpdateInput = { ...profile };
  if (ref.externalId && target && !target.externalId) data.externalId = ref.externalId;
  if (email && target && !target.email) {
    // Only claim the email if no other profile owns it
    const owner = await db.contact.findUnique({ where: { email }, select: { id: true } });
    if (!owner) data.email = email;
  }

  if (target) {
    return Object.keys(data).length ? db.contact.update({ where: { id: target.id }, data }) : target;
  }

  if (!ref.externalId && !email && !ref.anonymousId) return null;
  try {
    return await db.contact.create({
      data: {
        ...(profile as Prisma.ContactCreateInput),
        externalId: ref.externalId || null,
        email,
        anonymousId: ref.externalId || email ? null : ref.anonymousId || null,
      },
    });
  } catch {
    // Lost a create race on a unique key — the other request won; use its row
    return findContact(ref);
  }
}

/**
 * Move everything owned by `fromId` onto `intoId`, then delete `fromId`.
 * Attributes are shallow-merged (the known profile wins on conflicts).
 */
export async function mergeContacts(fromId: string, intoId: string): Promise<void> {
  if (fromId === intoId) return;
  await db.$transaction(async (tx) => {
    const [from, into] = await Promise.all([
      tx.contact.findUnique({ where: { id: fromId } }),
      tx.contact.findUnique({ where: { id: intoId } }),
    ]);
    if (!from || !into) return;

    await tx.pushSubscription.updateMany({ where: { contactId: fromId }, data: { contactId: intoId } });
    await tx.contactEvent.updateMany({ where: { contactId: fromId }, data: { contactId: intoId } });
    await tx.message.updateMany({ where: { contactId: fromId }, data: { contactId: intoId } });

    // Unique (groupId, contactId) / (journeyId, contactId): keep the known profile's row on conflict
    const [intoStates, intoRuns] = await Promise.all([
      tx.subscriptionState.findMany({ where: { contactId: intoId }, select: { groupId: true } }),
      tx.journeyRun.findMany({ where: { contactId: intoId }, select: { journeyId: true } }),
    ]);
    await tx.subscriptionState.updateMany({
      where: { contactId: fromId, groupId: { notIn: intoStates.map((s) => s.groupId) } },
      data: { contactId: intoId },
    });
    await tx.journeyRun.updateMany({
      where: { contactId: fromId, journeyId: { notIn: intoRuns.map((r) => r.journeyId) } },
      data: { contactId: intoId },
    });

    await tx.contact.delete({ where: { id: fromId } }); // cascades leftover conflicting rows
    await tx.contact.update({
      where: { id: intoId },
      data: {
        attributes: {
          ...((from.attributes as object) ?? {}),
          ...((into.attributes as object) ?? {}),
        },
        firstName: into.firstName ?? from.firstName,
        lastName: into.lastName ?? from.lastName,
        phone: into.phone ?? from.phone,
        email: into.email ?? from.email,
      },
    });
  });
}
